package com.juicyslew.moonstation14.ms14.atmos.machine.ui;

import com.juicyslew.moonstation14.ms14.atmos.machine.*;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.ResourceLocation;
import java.util.*;

/** Server-authoritative settings, resolved controls/capabilities and bounded telemetry. */
public record AtmosMachineControlSnapshot(int containerId, UUID session, long requestId, boolean accepted,
        AtmosMachineSettings.Values settings, Controls controls, double apcWatts, boolean apcKnown) implements CustomPacketPayload {
    public record Controls(String profileId, AtmosMachineProfile.Kind kind, boolean enabled, boolean pressure,
            boolean rate, boolean mixerRatio, boolean filterGas, boolean thermostat,
            double pressureMaxKpa,double rateMaxM3PerSecond,double thermostatMinK,double thermostatMaxK) {
        public Controls { if(profileId==null||profileId.isBlank()||profileId.length()>64||kind==null||
                !finite(pressureMaxKpa)||!finite(rateMaxM3PerSecond)||!finite(thermostatMinK)||!finite(thermostatMaxK)||pressureMaxKpa<0||rateMaxM3PerSecond<0||thermostatMinK<0||thermostatMaxK<thermostatMinK)throw new IllegalArgumentException("Invalid controls"); }
        public static Controls from(String profileId,AtmosMachineProfile p){if(p==null)throw new IllegalArgumentException("resolved profile required");
            boolean press=(p.pump()!=null&&p.pump().mode()==AtmosMachineProfile.PumpMode.PRESSURE)||p.mixer()!=null;
            boolean rate=(p.pump()!=null&&p.pump().mode()==AtmosMachineProfile.PumpMode.VOLUME)||p.filter()!=null;
            double pmax=p.pump()!=null&&p.pump().mode()==AtmosMachineProfile.PumpMode.PRESSURE?p.pump().maxPressureKpa().orElse(0d):p.mixer()!=null?p.mixer().maxPressureKpa():0;
            double rmax=p.pump()!=null&&p.pump().mode()==AtmosMachineProfile.PumpMode.VOLUME?p.pump().maxTransferRate().orElse(0d)/1000d:p.filter()!=null?p.filter().maxTransferRate()/1000d:0;
            return new Controls(profileId,p.kind(),p.pump()!=null||p.mixer()!=null||p.filter()!=null||p.thermostat()!=null,press,rate,p.mixer()!=null,p.filter()!=null,p.thermostat()!=null,pmax,rmax,p.thermostat()==null?0:p.thermostat().minimumTemperatureK(),p.thermostat()==null?0:p.thermostat().maximumTemperatureK());}
        boolean supports(AtmosMachineSettings.Values v){return v.enabled().isPresent()==enabled&&v.targetPressureKpa().isPresent()==pressure&&v.transferRateM3PerSecond().isPresent()==rate&&v.mixerFractionA().isPresent()==mixerRatio&&v.thermostatSetpointK().isPresent()==thermostat&&v.valveOpen().isEmpty()&&(!v.filterGas().isPresent()||filterGas);}
    }
    public static final Type<AtmosMachineControlSnapshot> TYPE=new Type<>(ResourceLocation.fromNamespaceAndPath("moonstation14","atmos_machine_snapshot"));
    public static final StreamCodec<RegistryFriendlyByteBuf,AtmosMachineControlSnapshot> STREAM_CODEC=StreamCodec.of((b,v)->v.encode(b),AtmosMachineControlSnapshot::decode);
    private void encode(RegistryFriendlyByteBuf b){b.writeVarInt(containerId);b.writeUUID(session);b.writeVarLong(requestId);b.writeBoolean(accepted);b.writeVarLong(settings.revision());int m=(settings.enabled().isPresent()?1:0)|(settings.targetPressureKpa().isPresent()?2:0)|(settings.transferRateM3PerSecond().isPresent()?4:0)|(settings.mixerFractionA().isPresent()?8:0)|(settings.filterGas().isPresent()?16:0)|(settings.thermostatSetpointK().isPresent()?32:0);b.writeByte(m);settings.enabled().ifPresent(b::writeBoolean);settings.targetPressureKpa().ifPresent(b::writeDouble);settings.transferRateM3PerSecond().ifPresent(b::writeDouble);settings.mixerFractionA().ifPresent(b::writeDouble);settings.filterGas().ifPresent(g->b.writeVarInt(g.ordinal()));settings.thermostatSetpointK().ifPresent(b::writeDouble);b.writeUtf(controls.profileId(),64);b.writeEnum(controls.kind());int c=(controls.enabled()?1:0)|(controls.pressure()?2:0)|(controls.rate()?4:0)|(controls.mixerRatio()?8:0)|(controls.filterGas()?16:0)|(controls.thermostat()?32:0);b.writeByte(c);b.writeDouble(controls.pressureMaxKpa());b.writeDouble(controls.rateMaxM3PerSecond());b.writeDouble(controls.thermostatMinK());b.writeDouble(controls.thermostatMaxK());b.writeDouble(apcWatts);b.writeBoolean(apcKnown);}
    private static AtmosMachineControlSnapshot decode(RegistryFriendlyByteBuf b){int id=b.readVarInt();UUID s=b.readUUID();long ack=b.readVarLong();boolean accepted=b.readBoolean();long rev=b.readVarLong();int mask=b.readUnsignedByte();if((mask&~63)!=0)throw new IllegalArgumentException("settings mask");var enabled=(mask&1)!=0?Optional.of(b.readBoolean()):Optional.<Boolean>empty();var pressure=(mask&2)!=0?Optional.of(b.readDouble()):Optional.<Double>empty();var rate=(mask&4)!=0?Optional.of(b.readDouble()):Optional.<Double>empty();var ratio=(mask&8)!=0?Optional.of(b.readDouble()):Optional.<Double>empty();Optional<com.juicyslew.moonstation14.ms14.atmos.core.GasType> gas=Optional.empty();if((mask&16)!=0){int gi=b.readVarInt();if(gi<0||gi>=com.juicyslew.moonstation14.ms14.atmos.core.GasType.values().length)throw new IllegalArgumentException("gas index");gas=Optional.of(com.juicyslew.moonstation14.ms14.atmos.core.GasType.values()[gi]);}var thermo=(mask&32)!=0?Optional.of(b.readDouble()):Optional.<Double>empty();var values=new AtmosMachineSettings.Values(rev,enabled,pressure,rate,ratio,gas,thermo,Optional.empty());String profile=b.readUtf(64);var kind=b.readEnum(AtmosMachineProfile.Kind.class);int cm=b.readUnsignedByte();if((cm&~63)!=0)throw new IllegalArgumentException("control mask");var controls=new Controls(profile,kind,(cm&1)!=0,(cm&2)!=0,(cm&4)!=0,(cm&8)!=0,(cm&16)!=0,(cm&32)!=0,b.readDouble(),b.readDouble(),b.readDouble(),b.readDouble());return new AtmosMachineControlSnapshot(id,s,ack,accepted,values,controls,b.readDouble(),b.readBoolean());}
    public AtmosMachineControlSnapshot { if(containerId<0||session==null||requestId< -1||settings==null||controls==null||!finite(apcWatts)||apcWatts<0)throw new IllegalArgumentException("Invalid snapshot");validate(settings,controls); }
    private static void validate(AtmosMachineSettings.Values v,Controls c){if(v.revision()<0||!c.supports(v))throw new IllegalArgumentException("settings capability mismatch");v.targetPressureKpa().ifPresent(x->{if(!finite(x)||x<0||x>c.pressureMaxKpa())throw new IllegalArgumentException("pressure bound");});v.transferRateM3PerSecond().ifPresent(x->{if(!finite(x)||x<0||x>c.rateMaxM3PerSecond())throw new IllegalArgumentException("rate bound");});v.mixerFractionA().ifPresent(x->{if(!finite(x)||x<0||x>1)throw new IllegalArgumentException("ratio bound");});v.thermostatSetpointK().ifPresent(x->{if(!finite(x)||x<c.thermostatMinK()||x>c.thermostatMaxK())throw new IllegalArgumentException("thermostat bound");});}
    private static boolean finite(double n){return Double.isFinite(n);}
    @Override public Type<? extends CustomPacketPayload> type(){return TYPE;}
}
